head.script:
(function(){
    const XHTML_NS="http://www.w3.org/1999/xhtml";
    const root=document.querySelector("foreignObject").firstElementChild;
    const originalCreateElement=document.createElement.bind(document);
    const originalCreateElementNS=document.createElementNS.bind(document);
    Object.defineProperty(document,"head",{get(){return root.querySelector("head")},configurable:true});
    Object.defineProperty(document,"body",{get(){return root.querySelector("body")},configurable:true});
    Object.defineProperty(document,"documentElement",{get(){return root},configurable:true});
    document.createElement=function(tagName,options){
        if(typeof tagName==="string"){return originalCreateElementNS(XHTML_NS,tagName,options)}
        return originalCreateElement(tagName,options)
    };
    document.createElementNS=function(namespaceURI,qualifiedName,options){
        if(namespaceURI==null||namespaceURI===XHTML_NS){return originalCreateElementNS(XHTML_NS,qualifiedName,options)}
        return originalCreateElementNS(namespaceURI,qualifiedName,options)
    };
})();

body.script:
(function() {
    // 1. Super AdBlocker & Anti-Redirect Interceptor
    const adPatterns = [
        'adcash', 'popcash', 'smartpop', 'syndication', 'doubleclick',
        'googleadservices', 'adnxs', 'trafficjunky', 'propeller',
        'onclick', 'adsterra', 'exoclick', 'zergnet', 'revcontent',
        'taboola', 'outbrain', 'bet365', '1xbet', 'vortex', 'hilltopads'
    ];
    const _origOpen = window.open;
    window.open = function(url, target, features) {
        if (!url) return null;
        const sUrl = String(url).toLowerCase();
        for (let i = 0; i < adPatterns.length; i++) {
            if (sUrl.indexOf(adPatterns[i]) !== -1) {
                console.log('[يونس AdBlocker] Blocked popup:', url);
                return null;
            }
        }
        if (sUrl === 'about:blank' || sUrl.startsWith('javascript:')) {
            return null;
        }
        return _origOpen.call(window, url, target, features);
    };

    // 2. Synthesized Audio Feedback (Web Audio API)
    let audioCtx = null;
    function playBeep(freq, type, duration) {
        try {
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            if (audioCtx.state === 'suspended') audioCtx.resume();
            const osc = audioCtx.createOscillator();
            const gain = audioCtx.createGain();
            osc.type = type || 'sine';
            osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
            gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
            gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
            osc.connect(gain);
            gain.connect(audioCtx.destination);
            osc.start();
            osc.stop(audioCtx.currentTime + duration);
        } catch(e) {}
    }

    // 3. Authentication & 3-Try Lockout Engine
    const AUTH_PIN = '7081';
    const MAX_TRIES = 3;
    let currentInput = '';
    let isUnlocked = false;
    let failedCount = 0;

    try {
        if (localStorage.getItem('_younus_sys_locked') === 'true') {
            failedCount = MAX_TRIES;
        } else {
            failedCount = parseInt(localStorage.getItem('_younus_attempts_spent') || '0', 10);
            if (isNaN(failedCount)) failedCount = 0;
            if (failedCount >= MAX_TRIES) {
                localStorage.setItem('_younus_sys_locked', 'true');
            }
        }
    } catch(e) {}

    const authOverlay = document.getElementById('auth-overlay');
    const authActiveBox = document.getElementById('auth-active-box');
    const authLockedBox = document.getElementById('auth-locked-box');
    const attemptsBadge = document.getElementById('attempts-badge');
    const pinDots = [
        document.getElementById('dot-0'),
        document.getElementById('dot-1'),
        document.getElementById('dot-2'),
        document.getElementById('dot-3')
    ];

    function updateDots() {
        for (let i = 0; i < 4; i++) {
            if (i < currentInput.length) {
                pinDots[i].classList.add('filled');
            } else {
                pinDots[i].classList.remove('filled');
                pinDots[i].classList.remove('error');
            }
        }
    }

    function updateAttemptsUI() {
        const remaining = Math.max(0, MAX_TRIES - failedCount);
        if (remaining <= 0) {
            authActiveBox.style.display = 'none';
            authLockedBox.style.display = 'block';
        } else {
            attemptsBadge.textContent = remaining + ' Attempt' + (remaining === 1 ? '' : 's') + ' Remaining';
            if (remaining === 1) {
                attemptsBadge.className = 'attempts-badge danger';
            } else if (remaining === 2) {
                attemptsBadge.className = 'attempts-badge warn';
            } else {
                attemptsBadge.className = 'attempts-badge';
            }
        }
    }

    function openAuthModal() {
        if (isUnlocked) return;
        currentInput = '';
        updateDots();
        updateAttemptsUI();
        authOverlay.classList.add('active');
    }

    function closeAuthModal() {
        authOverlay.classList.remove('active');
        currentInput = '';
        updateDots();
    }

    function appendDigit(digit) {
        if (failedCount >= MAX_TRIES) return;
        if (currentInput.length < 4) {
            currentInput += digit;
            playBeep(480 + (currentInput.length * 60), 'sine', 0.08);
            updateDots();
            if (currentInput.length === 4) {
                setTimeout(submitPin, 180);
            }
        }
    }

    function deleteDigit() {
        if (currentInput.length > 0) {
            currentInput = currentInput.slice(0, -1);
            playBeep(340, 'triangle', 0.08);
            updateDots();
        }
    }

    function submitPin() {
        if (failedCount >= MAX_TRIES) return;
        if (currentInput === AUTH_PIN) {
            // Success
            isUnlocked = true;
            playBeep(523, 'triangle', 0.1);
            setTimeout(function() { playBeep(659, 'triangle', 0.12); }, 100);
            setTimeout(function() { playBeep(784, 'triangle', 0.2); }, 200);

            try {
                localStorage.removeItem('_younus_attempts_spent');
            } catch(e) {}
            closeAuthModal();
            launchPortal();
        } else {
            // Failed Attempt
            failedCount++;
            playBeep(180, 'sawtooth', 0.25);
            try {
                localStorage.setItem('_younus_attempts_spent', String(failedCount));
            } catch(e) {}

            for (let i = 0; i < 4; i++) {
                pinDots[i].classList.add('error');
            }

            setTimeout(function() {
                currentInput = '';
                updateDots();
                if (failedCount >= MAX_TRIES) {
                    try {
                        localStorage.setItem('_younus_sys_locked', 'true');
                    } catch(e) {}
                    updateAttemptsUI();
                } else {
                    updateAttemptsUI();
                }
            }, 400);
        }
    }

    // Keypad listeners
    document.querySelectorAll('.key-btn[data-key]').forEach(function(btn) {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            appendDigit(btn.getAttribute('data-key'));
        });
    });

    const keyDel = document.getElementById('key-del');
    const keyEnter = document.getElementById('key-enter');
    if (keyDel) {
        keyDel.addEventListener('click', function(e) {
            e.stopPropagation();
            deleteDigit();
        });
    }
    if (keyEnter) {
        keyEnter.addEventListener('click', function(e) {
            e.stopPropagation();
            if (currentInput.length > 0) submitPin();
        });
    }

    // Physical keyboard listener
    window.addEventListener('keydown', function(e) {
        if (authOverlay.classList.contains('active')) {
            if (e.key >= '0' && e.key <= '9') {
                appendDigit(e.key);
            } else if (e.key === 'Backspace') {
                deleteDigit();
            } else if (e.key === 'Enter') {
                submitPin();
            } else if (e.key === 'Escape') {
                closeAuthModal();
            }
        } else if (e.key === 'Escape') {
            if (isUnlocked) panicCloak();
        }
    });

    // Click anywhere on screen to trigger PIN entry
    document.addEventListener('click', function(e) {
        if (isUnlocked) return;
        if (authOverlay.classList.contains('active')) {
            if (e.target === authOverlay) closeAuthModal();
            return;
        }
        openAuthModal();
    });

    const openPortalBtn = document.getElementById('open-portal-btn');
    if (openPortalBtn) {
        openPortalBtn.addEventListener('click', function(e) {
            e.stopPropagation();
            openAuthModal();
        });
    }

    // 4. Live Proxy Mirrors & Portal Engine
    const LIVE_MIRRORS = [
        'https://cirrusbk6l.planet35.com',
        'https://drifttt82.chickenkiller.com',
        'https://flint7boq.irqsistemas.net',
        'https://onyxjbxy.sakidumarwana.com.np',
        'https://driftz9ip.abratec.com.br',
        'https://novajfag.amadeuspiano.com'
    ];

    let activeMirror = LIVE_MIRRORS[0];
    let mirrorIdx = 0;
    let activeTabName = 'home';

    const splash = document.getElementById('connect-splash');
    const portalView = document.getElementById('portal-view');
    const nodeNameLabel = document.getElementById('node-name-label');

    const viewHome = document.getElementById('view-home');
    const frameBrowser = document.getElementById('frame-browser');
    const frameGames = document.getElementById('frame-games');
    const frameMovies = document.getElementById('frame-movies');
    const frameYoutube = document.getElementById('frame-youtube');

    async function pingMirror(url) {
        const ctrl = new AbortController();
        const timer = setTimeout(function() { ctrl.abort(); }, 2500);
        try {
            const res = await fetch(url + '/modules/browser/index.html', {
                method: 'GET',
                mode: 'no-cors',
                signal: ctrl.signal
            });
            clearTimeout(timer);
            return url;
        } catch (err) {
            clearTimeout(timer);
            throw err;
        }
    }

    async function findFastestMirror() {
        try {
            const fastest = await Promise.any(LIVE_MIRRORS.map(function(m) { return pingMirror(m); }));
            return fastest;
        } catch (e) {
            return LIVE_MIRRORS[0];
        }
    }

    async function launchPortal() {
        splash.style.display = 'flex';
        try {
            activeMirror = await findFastestMirror();
            mirrorIdx = LIVE_MIRRORS.indexOf(activeMirror);
            if (mirrorIdx === -1) mirrorIdx = 0;

            const host = new URL(activeMirror).hostname.split('.')[0];
            if (nodeNameLabel) nodeNameLabel.textContent = host + ' (Live)';

            portalView.classList.add('active');
            switchTab('home');

            setTimeout(function() {
                splash.style.display = 'none';
            }, 300);
        } catch (err) {
            splash.style.display = 'none';
            portalView.classList.add('active');
            switchTab('home');
        }
    }

    function switchTab(tab) {
        activeTabName = tab;
        ['home', 'browser', 'games', 'movies', 'youtube'].forEach(function(t) {
            const tabBtn = document.getElementById('tab-' + t);
            if (tabBtn) tabBtn.classList.toggle('active', t === tab);
        });

        // Hide all views first
        viewHome.style.display = 'none';
        frameBrowser.classList.remove('active');
        frameGames.classList.remove('active');
        frameMovies.classList.remove('active');
        frameYoutube.classList.remove('active');

        if (tab === 'home') {
            viewHome.style.display = 'flex';
        } else if (tab === 'browser') {
            if (!frameBrowser.src || frameBrowser.src === 'about:blank') {
                frameBrowser.src = activeMirror + '/modules/browser/index.html';
            }
            frameBrowser.classList.add('active');
        } else if (tab === 'games') {
            if (!frameGames.src || frameGames.src === 'about:blank') {
                frameGames.src = activeMirror + '/modules/lib/index.html';
            }
            frameGames.classList.add('active');
        } else if (tab === 'movies') {
            if (!frameMovies.src || frameMovies.src === 'about:blank') {
                frameMovies.src = activeMirror + '/modules/movies/index.html';
            }
            frameMovies.classList.add('active');
        } else if (tab === 'youtube') {
            if (!frameYoutube.src || frameYoutube.src === 'about:blank') {
                frameYoutube.src = activeMirror + '/modules/youtube/index.html';
            }
            frameYoutube.classList.add('active');
        }
    }

    window.openModule = function(mod) {
        switchTab(mod);
    };

    document.getElementById('tab-home').addEventListener('click', function() { switchTab('home'); });
    document.getElementById('tab-browser').addEventListener('click', function() { switchTab('browser'); });
    document.getElementById('tab-games').addEventListener('click', function() { switchTab('games'); });
    document.getElementById('tab-movies').addEventListener('click', function() { switchTab('movies'); });
    document.getElementById('tab-youtube').addEventListener('click', function() { switchTab('youtube'); });
    document.getElementById('brand-logo-btn').addEventListener('click', function() { switchTab('home'); });

    // Quick Search Input
    const quickInput = document.getElementById('quick-url-input');
    const quickSearchBtn = document.getElementById('btn-quick-search');
    function executeQuickSearch() {
        const val = (quickInput.value || '').trim();
        if (!val) {
            switchTab('browser');
            return;
        }
        let targetUrl = val;
        if (!val.startsWith('http://') && !val.startsWith('https://')) {
            if (val.indexOf('.') !== -1 && val.indexOf(' ') === -1) {
                targetUrl = 'https://' + val;
            } else {
                targetUrl = 'https://www.google.com/search?q=' + encodeURIComponent(val);
            }
        }
        switchTab('browser');
        frameBrowser.src = activeMirror + '/modules/browser/index.html#' + encodeURIComponent(targetUrl);
    }
    if (quickSearchBtn) quickSearchBtn.addEventListener('click', executeQuickSearch);
    if (quickInput) {
        quickInput.addEventListener('keydown', function(e) {
            if (e.key === 'Enter') executeQuickSearch();
        });
    }

    // Node Switcher
    const btnNodeCycle = document.getElementById('btn-node-cycle');
    if (btnNodeCycle) {
        btnNodeCycle.addEventListener('click', function() {
            mirrorIdx = (mirrorIdx + 1) % LIVE_MIRRORS.length;
            activeMirror = LIVE_MIRRORS[mirrorIdx];
            const host = new URL(activeMirror).hostname.split('.')[0];
            if (nodeNameLabel) nodeNameLabel.textContent = host + ' (Live)';

            // Reload active frame with new node
            if (activeTabName === 'browser') frameBrowser.src = activeMirror + '/modules/browser/index.html';
            else if (activeTabName === 'games') frameGames.src = activeMirror + '/modules/lib/index.html';
            else if (activeTabName === 'movies') frameMovies.src = activeMirror + '/modules/movies/index.html';
            else if (activeTabName === 'youtube') frameYoutube.src = activeMirror + '/modules/youtube/index.html';
        });
    }

    // Tab Cloaker (Google Classroom disguise)
    let isCloaked = false;
    const btnTabCloak = document.getElementById('btn-tab-cloak');
    if (btnTabCloak) {
        btnTabCloak.addEventListener('click', function() {
            isCloaked = !isCloaked;
            if (isCloaked) {
                document.title = 'Classes - Google Classroom';
                const link = document.querySelector("link[rel*='icon']") || document.createElement('link');
                link.type = 'image/x-icon';
                link.rel = 'shortcut icon';
                link.href = 'https://ssl.gstatic.com/classroom/favicon.png';
                document.getElementsByTagName('head')[0].appendChild(link);
                btnTabCloak.textContent = '🎭 Uncloak';
            } else {
                document.title = 'APStudy | Math and Language Arts Tutoring';
                btnTabCloak.textContent = '🎭 Disguise';
            }
        });
    }

    // Panic Button (Esc)
    function panicCloak() {
        portalView.classList.remove('active');
        frameBrowser.src = 'about:blank';
        frameGames.src = 'about:blank';
        frameMovies.src = 'about:blank';
        frameYoutube.src = 'about:blank';
        isUnlocked = false;
        closeAuthModal();
        if (lofiAudio && !lofiAudio.paused) {
            lofiAudio.pause();
            lofiPlayBtn.textContent = '▶';
        }
    }
    const btnPanic = document.getElementById('btn-panic-cloak');
    if (btnPanic) btnPanic.addEventListener('click', panicCloak);

    // Lo-Fi Audio Player
    const lofiAudio = document.getElementById('lofi-audio');
    const lofiPlayBtn = document.getElementById('lofi-play-btn');
    const lofiStatusText = document.getElementById('lofi-status-text');
    if (lofiPlayBtn && lofiAudio) {
        lofiPlayBtn.addEventListener('click', function() {
            if (lofiAudio.paused) {
                lofiAudio.play().then(function() {
                    lofiPlayBtn.textContent = '⏸';
                    lofiStatusText.textContent = 'Streaming live chill Lo-Fi beats...';
                }).catch(function() {
                    lofiStatusText.textContent = 'Click again to permit audio stream';
                });
            } else {
                lofiAudio.pause();
                lofiPlayBtn.textContent = '▶';
                lofiStatusText.textContent = 'Paused';
            }
        });
    }
})();
